pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ReentrantAttacker {
    C target;
    bool public reentered;
    uint256 public reentrantAmount = 0.5 ether;

    constructor(C _target) {
        target = _target;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdraw(reentrantAmount);
        }
    }

    function attack() external payable {
        target.deposit{value: msg.value}();
        target.withdraw(reentrantAmount);
    }
}

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(c);
    }

    function testRegression_property() public {
        vm.deal(address(attacker), 1 ether);
        vm.prank(address(attacker));
        attacker.attack{value: 1 ether}();

        // After the attack, in the reference the contract still has 1 ether
        // (because reentrant withdraw reverted), in the buggy version it has 0
        assertTrue(address(c).balance == 1 ether);
    }
}

