    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        Reenter attacker = new Reenter(c);
        vm.deal(address(attacker), 1 ether);
        vm.prank(address(attacker));
        attacker.attack();
        // Reference: reentrant call reverts, so contract retains 0.5 ether
        // Buggy: reentrant call succeeds, so contract balance is 0
        assertTrue(address(c).balance == 0.5 ether);
    }
}

