pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ReentrantAttacker {
    C public target;
    uint256 public reentrantAmount;
    constructor(C _target) { target = _target; }
    function attack(uint256 amount) external payable {
        reentrantAmount = amount;
        target.deposit{value: msg.value}();
        target.withdraw(amount);
    }
    receive() external payable {
        if (address(target).balance >= reentrantAmount) {
            target.withdraw(reentrantAmount);
        }
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy attacker
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        uint256 depositAmount = 1 ether;
        uint256 withdrawAmount = 0.5 ether;
        // Fund attacker
        vm.deal(address(attacker), depositAmount);
        // Attacker deposits and initiates withdraw with reentrancy
        // The revert status of the outer call captures the difference
        bool success;
        try attacker.attack(withdrawAmount) {
            success = true;
        } catch {
            success = false;
        }
        // In reference (correct), the reentrant call reverts, so the attacker's outer call reverts; success = false
        // In buggy version, the reentrant call succeeds, draining everything; success = true
        // We assert that the reference behavior is failure (revert)
        assertTrue(!success, "Reference should revert on reentrant withdraw");
    }
}

