import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Alice deposits 1 wei
        address alice = address(0x1);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.deposit{value: 1 wei}();

        // Alice tries to withdraw 2 wei, which should revert in reference (require check) but not in bug
        vm.prank(alice);
        // Use try/catch to capture revert behavior
        bool success;
        try c.withdraw(2 wei) {
            success = true;
        } catch {
            success = false;
        }

        // In reference, withdraw reverts (success == false); in bug, it succeeds (success == true)
        // We assert that the withdraw did NOT revert (i.e., buggy behavior)
        assertTrue(success);
    }
}

