pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Alice deposits 1 wei
        vm.deal(address(1), 1 wei);
        vm.prank(address(1));
        c.deposit{value: 1 wei}();

        // Bob tries to withdraw 2 wei
        vm.prank(address(2));
        bool ok;
        try c.withdraw(2 wei) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: withdraw reverts (ok = false). Bug: withdraw succeeds (ok = true).
        assertTrue(!ok, "Withdraw should revert in reference, but succeeded in bug");
    }
}

