pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deposit 1 wei from a non-creator address
        address attacker = address(0x1234);
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        c.deposit{value: 1 wei}();

        // The reference contract reverts migrateTo when called by non-creator
        // The buggy version does not revert and transfers the balance to 'to'
        vm.prank(attacker);
        c.migrateTo(attacker);

        // In the reference, this call would have reverted, so balance stays.
        // In the buggy version, the attacker gets the whole contract balance.
        bool ok;
        try this.isBalanceNonZero(address(c)) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }

    function isBalanceNonZero(address _target) public view returns (bool) {
        return _target.balance > 0;
    }
}

